1	import { lazy, Suspense, useEffect } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	import { supabase } from "@/integrations/supabase/client";
14	
15	// Eager imports — core pages users navigate between constantly (no Suspense flash)
16	import Index from "./pages/Index";
17	import Auth from "./pages/Auth";
18	import Settings from "./pages/Settings";
19	import Profile from "./pages/Profile";
20	import Billing from "./pages/Billing";
21	import Team from "./pages/Team";
22	import Tasks from "./pages/Tasks";
23	
24	// Sidebar-accessible pages — eager to avoid flash on click
25	import Changelog from "./pages/Changelog";
26	import RequestFeature from "./pages/RequestFeature";
27	
28	// Lazy imports — infrequent or large pages
29	const Admin = lazy(() => import("./pages/Admin"));
30	const NotFound = lazy(() => import("./pages/NotFound"));
31	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
32	const BookDemo = lazy(() => import("./pages/BookDemo"));
33	const Apply = lazy(() => import("./pages/Apply"));
34	const CareerPage = lazy(() => import("./pages/CareerPage"));
35	const CareerSettings = lazy(() => import("./pages/CareerSettings"));
36	const LandingPage = lazy(() => import("@/components/LandingPage"));
37	
38	const queryClient = new QueryClient({
39	  defaultOptions: {
40	    queries: {
41	      staleTime: 5 * 60 * 1000,
42	      gcTime: 10 * 60 * 1000,
43	      refetchOnWindowFocus: false,
44	      refetchOnMount: false,
45	      retry: 1,
46	    },
47	  },
48	});
49	
50	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
51	const PageLoader = () => (
52	  <div className="flex h-svh w-full overflow-hidden">
53	    {/* Sidebar skeleton — matches sidebar width */}
54	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
55	      <div className="px-4 py-4">
56	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
57	      </div>
58	      <div className="border-t border-border" />
59	      <div className="p-3 space-y-2">
60	        {[1, 2, 3, 4].map((i) => (
61	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
62	        ))}
63	      </div>
64	    </div>
65	    {/* Content area skeleton */}
66	    <div className="flex-1 flex flex-col min-w-0">
67	      {/* Header skeleton */}
68	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
69	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
70	        <div className="flex items-center gap-3">
71	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
72	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
73	        </div>
74	      </div>
75	      {/* Body skeleton */}
76	      <div className="flex-1 overflow-y-auto p-6">
77	        <div className="max-w-5xl mx-auto space-y-4">
78	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
79	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
80	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
81	            {[1, 2, 3, 4].map((i) => (
82	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
83	            ))}
84	          </div>
85	        </div>
86	      </div>
87	    </div>
88	  </div>
89	);
90	
91	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
92	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
93	  const { isAdmin, loading } = useAuth();
94	
95	  // Don't block rendering while loading — only gate when we know maintenance is on
96	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
97	  return <>{children}</>;
98	};
99	
100	const RootRoute = () => {
101	  const { user, loading } = useAuth();
102	  if (loading) return <PageLoader />;
103	  return user ? <Index /> : <LandingPage />;
104	};
105	
106	/** Silently prefetches sidebar-linked pages so they open instantly on first click */
107	const DataPrefetcher = () => {
108	  const { user } = useAuth();
109	  const qc = useQueryClient();
110	
111	  useEffect(() => {
112	    // Prefetch public data that doesn't require auth
113	    qc.prefetchQuery({
114	      queryKey: ["changelog_public"],
115	      queryFn: async () => {
116	        const { data } = await (supabase as any)
117	          .from("changelog")
118	          .select("id, version, title, description, category, published_at")
119	          .eq("status", "published")
120	          .order("published_at", { ascending: false });
121	        return data ?? [];
122	      },
123	      staleTime: 5 * 60 * 1000,
124	    });
125	    qc.prefetchQuery({
126	      queryKey: ["feature_requests"],
127	      queryFn: async () => {
128	        const { data } = await (supabase as any)
129	          .from("feature_requests")
130	          .select("*")
131	          .order("created_at", { ascending: false });
132	        return data ?? [];
133	      },
134	      staleTime: 5 * 60 * 1000,
135	    });
136	  }, []);
137	
138	  useEffect(() => {
139	    if (!user) return;
140	    qc.prefetchQuery({
141	      queryKey: ["my_feature_votes"],
142	      queryFn: async () => {
143	        const { data } = await (supabase as any)
144	          .from("feature_request_votes")
145	          .select("feature_request_id")
146	          .eq("user_id", user.id);
147	        return (data ?? []).map((v: any) => v.feature_request_id);
148	      },
149	      staleTime: 5 * 60 * 1000,
150	    });
151	  }, [user?.id]);
152	
153	  return null;
154	};
155	
156	const App = () => (
157	  <QueryClientProvider client={queryClient}>
158	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
159	      <AuthProvider>
160	        <DataPrefetcher />
161	        <TooltipProvider>
162	          <Sonner />
163	          <BrowserRouter>
164	            <SeoHead />
165	            <Suspense fallback={<PageLoader />}>
166	              <Routes>
167	                {/* Public pages — outside MaintenanceGate so candidates can always access */}
168	                <Route path="/apply/:jobId" element={<Apply />} />
169	                <Route path="/careers/:slug" element={<CareerPage />} />
170	                <Route path="*" element={
171	                  <MaintenanceGate>
172	                    <Routes>
173	                      <Route path="/auth" element={<Auth />} />
174	                      <Route path="/" element={<RootRoute />} />
175	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
176	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
177	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
178	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
179	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
180	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
181	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
182	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
183	                      <Route path="/book-demo" element={<BookDemo />} />
184	                      <Route path="/request-feature" element={<RequestFeature />} />
185	                      <Route path="/changelog" element={<Changelog />} />
186	                      <Route path="/payment/callback" element={<PaymentCallback />} />
187	                      <Route path="*" element={<NotFound />} />
188	                    </Routes>
189	                  </MaintenanceGate>
190	                } />
191	              </Routes>
192	            </Suspense>
193	            <ChatWidget />
194	          </BrowserRouter>
195	        </TooltipProvider>
196	      </AuthProvider>
197	    </ThemeProvider>
198	  </QueryClientProvider>
199	);
200	
201	export default App;
202	
