1	import { useState } from "react";
2	import { toast } from "sonner";
3	import { format } from "date-fns";
4	import {
5	  Users,
6	  Crown,
7	  Shield,
8	  UserPlus,
9	  Trash2,
10	  Loader2,
11	  Mail,
12	  RotateCw,
13	} from "lucide-react";
14	import SidebarLayout from "@/components/SidebarLayout";
15	import { FadeIn } from "@/components/ui/fade-in";
16	import { StaggerList } from "@/components/ui/stagger-list";
17	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
18	import { Button } from "@/components/ui/button";
19	import { Input } from "@/components/ui/input";
20	import { Badge } from "@/components/ui/badge";
21	import { Skeleton } from "@/components/ui/skeleton";
22	import {
23	  Select,
24	  SelectContent,
25	  SelectItem,
26	  SelectTrigger,
27	  SelectValue,
28	} from "@/components/ui/select";
29	import {
30	  Table,
31	  TableBody,
32	  TableCell,
33	  TableHead,
34	  TableHeader,
35	  TableRow,
36	} from "@/components/ui/table";
37	import {
38	  AlertDialog,
39	  AlertDialogAction,
40	  AlertDialogCancel,
41	  AlertDialogContent,
42	  AlertDialogDescription,
43	  AlertDialogFooter,
44	  AlertDialogHeader,
45	  AlertDialogTitle,
46	  AlertDialogTrigger,
47	} from "@/components/ui/alert-dialog";
48	import { useTeam, type TeamMember, type TeamInvitation } from "@/hooks/useTeam";
49	import { supabase } from "@/integrations/supabase/client";
50	import { useAuth } from "@/hooks/useAuth";
51	
52	type TeamRole = "owner" | "admin" | "member";
53	
54	const ROLE_LABELS: Record<TeamRole, string> = {
55	  owner: "Owner",
56	  admin: "Admin",
57	  member: "Member",
58	};
59	
60	const ROLE_VARIANTS: Record<TeamRole, "default" | "secondary" | "outline"> = {
61	  owner: "default",
62	  admin: "secondary",
63	  member: "outline",
64	};
65	
66	function RoleBadge({ role }: { role: TeamRole }) {
67	  const Icon = role === "owner" ? Crown : role === "admin" ? Shield : Users;
68	  return (
69	    <Badge variant={ROLE_VARIANTS[role]} className="gap-1 text-xs font-medium">
70	      <Icon className="h-3 w-3" />
71	      {ROLE_LABELS[role]}
72	    </Badge>
73	  );
74	}
75	
76	function MembersSkeleton() {
77	  return (
78	    <div className="space-y-3">
79	      {[1, 2, 3].map((i) => (
80	        <div key={i} className="flex items-center gap-4 px-4 py-3">
81	          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
82	          <div className="flex-1 space-y-1.5">
83	            <Skeleton className="h-4 w-48" />
84	            <Skeleton className="h-3 w-32" />
85	          </div>
86	          <Skeleton className="h-6 w-16 rounded-full" />
87	          <Skeleton className="h-8 w-8 rounded" />
88	        </div>
89	      ))}
90	    </div>
91	  );
92	}
93	
94	const Team = () => {
95	  const { user } = useAuth();
96	  const { team, members, invitations, myRole, isLoading, refetch } = useTeam();
97	
98	  const [inviteEmail, setInviteEmail] = useState("");
99	  const [inviteRole, setInviteRole] = useState<"admin" | "member">("member");
100	  const [isSendingInvite, setIsSendingInvite] = useState(false);
101	  const [revokingId, setRevokingId] = useState<string | null>(null);
102	  const [removingId, setRemovingId] = useState<string | null>(null);
103	  const [updatingRoleId, setUpdatingRoleId] = useState<string | null>(null);
104	
105	  const canManage = myRole === "owner" || myRole === "admin";
106	
107	  async function handleInvite(e: React.FormEvent) {
108	    e.preventDefault();
109	    if (!inviteEmail.trim() || !team?.id) return;
110	
111	    setIsSendingInvite(true);
112	    try {
113	      const { data: { session } } = await supabase.auth.getSession();
114	      if (!session?.access_token) throw new Error("Not authenticated");
115	
116	      const res = await fetch(
117	        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/send-team-invite`,
118	        {
119	          method: "POST",
120	          headers: {
121	            "Content-Type": "application/json",
122	            "Authorization": `Bearer ${session.access_token}`,
123	            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
124	          },
125	          body: JSON.stringify({
126	            team_id: team.id,
127	            email: inviteEmail.trim().toLowerCase(),
128	            role: inviteRole,
129	          }),
130	        }
131	      );
132	
133	      const json = await res.json();
134	      if (!res.ok) throw new Error(json.error || "Failed to send invitation");
135	
136	      toast.success(`Invitation sent to ${inviteEmail.trim()}`);
137	      setInviteEmail("");
138	      refetch();
139	    } catch (err: unknown) {
140	      const msg = err instanceof Error ? err.message : "Failed to send invitation";
141	      toast.error(msg);
142	    } finally {
143	      setIsSendingInvite(false);
144	    }
145	  }
146	
147	  async function handleRevokeInvite(id: string, email: string) {
148	    setRevokingId(id);
149	    try {
150	      const { error } = await (supabase as any)
151	        .from("team_invitations")
152	        .update({ status: "revoked" })
153	        .eq("id", id);
154	
155	      if (error) throw error;
156	
157	      toast.success(`Invitation to ${email} revoked`);
158	      refetch();
159	    } catch (err: unknown) {
160	      toast.error("Failed to revoke invitation");
161	    } finally {
162	      setRevokingId(null);
163	    }
164	  }
165	
166	  async function handleChangeRole(member: TeamMember, newRole: TeamRole) {
167	    if (newRole === member.role) return;
168	    setUpdatingRoleId(member.id);
169	    try {
170	      const { error } = await (supabase as any)
171	        .from("team_members")
172	        .update({ role: newRole })
173	        .eq("id", member.id);
174	
175	      if (error) throw error;
176	
177	      toast.success(`Role updated to ${ROLE_LABELS[newRole]}`);
178	      refetch();
179	    } catch (err: unknown) {
180	      toast.error("Failed to update role");
181	    } finally {
182	      setUpdatingRoleId(null);
183	    }
184	  }
185	
186	  async function handleRemoveMember(member: TeamMember) {
187	    setRemovingId(member.id);
188	    try {
189	      const { error } = await (supabase as any)
190	        .from("team_members")
191	        .delete()
192	        .eq("id", member.id);
193	
194	      if (error) throw error;
195	
196	      toast.success("Member removed from team");
197	      refetch();
198	    } catch (err: unknown) {
199	      toast.error("Failed to remove member");
200	    } finally {
201	      setRemovingId(null);
202	    }
203	  }
204	
205	  const pendingInvitations = invitations.filter((inv) => inv.status === "pending");
206	  const nonOwnerMembers = members.filter((m) => m.role !== "owner");
207	
208	  return (
209	    <SidebarLayout>
210	      <main className="w-full max-w-2xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
211	        <FadeIn>
212	          <div className="flex items-center justify-between mb-1">
213	            <h1 className="text-2xl font-bold text-foreground">Team</h1>
214	            {team && (
215	              <span className="text-sm text-muted-foreground">{team.name}</span>
216	            )}
217	          </div>
218	          <p className="text-sm text-muted-foreground mb-6">
219	            Manage your team members and pending invitations.
220	          </p>
221	        </FadeIn>
222	
223	        <StaggerList className="space-y-6" stagger={0.08}>
224	          {/* Invite card — only visible to owners/admins */}
225	          {canManage && (
226	            <Card className="border border-border/60 shadow-sm">
227	              <CardHeader className="pb-3">
228	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
229	                  <UserPlus className="h-4 w-4 text-primary" />
230	                  Invite a teammate
231	                </CardTitle>
232	              </CardHeader>
233	              <CardContent>
234	                <form onSubmit={handleInvite} className="flex flex-col sm:flex-row gap-2">
235	                  <div className="relative flex-1">
236	                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
237	                    <Input
238	                      type="email"
239	                      placeholder="colleague@company.com"
240	                      value={inviteEmail}
241	                      onChange={(e) => setInviteEmail(e.target.value)}
242	                      className="pl-9"
243	                      required
244	                      disabled={isSendingInvite}
245	                    />
246	                  </div>
247	                  <Select
248	                    value={inviteRole}
249	                    onValueChange={(v) => setInviteRole(v as "admin" | "member")}
250	                    disabled={isSendingInvite}
251	                  >
252	                    <SelectTrigger className="w-full sm:w-32">
253	                      <SelectValue />
254	                    </SelectTrigger>
255	                    <SelectContent>
256	                      <SelectItem value="member">Member</SelectItem>
257	                      <SelectItem value="admin">Admin</SelectItem>
258	                    </SelectContent>
259	                  </Select>
260	                  <Button
261	                    type="submit"
262	                    disabled={isSendingInvite || !inviteEmail.trim()}
263	                    className="gap-1.5 shrink-0"
264	                  >
265	                    {isSendingInvite ? (
266	                      <Loader2 className="h-4 w-4 animate-spin" />
267	                    ) : (
268	                      <UserPlus className="h-4 w-4" />
269	                    )}
270	                    Send invite
271	                  </Button>
272	                </form>
273	              </CardContent>
274	            </Card>
275	          )}
276	
277	          {/* Pending invitations */}
278	          {(pendingInvitations.length > 0 || (isLoading && canManage)) && (
279	            <Card className="border border-border/60 shadow-sm">
280	              <CardHeader className="pb-3">
281	                <div className="flex items-center justify-between">
282	                  <CardTitle className="text-sm font-semibold flex items-center gap-2">
283	                    <Mail className="h-4 w-4 text-primary" />
284	                    Pending invitations
285	                    {!isLoading && (
286	                      <Badge variant="secondary" className="ml-1 text-xs">
287	                        {pendingInvitations.length}
288	                      </Badge>
289	                    )}
290	                  </CardTitle>
291	                  <Button
292	                    variant="ghost"
293	                    size="icon"
294	                    className="h-7 w-7"
295	                    onClick={() => refetch()}
296	                    disabled={isLoading}
297	                    aria-label="Refresh invitations"
298	                  >
299	                    <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
300	                  </Button>
301	                </div>
302	              </CardHeader>
303	              <CardContent className="p-0">
304	                {isLoading ? (
305	                  <div className="space-y-2 p-4">
306	                    {[1, 2].map((i) => (
307	                      <Skeleton key={i} className="h-10 w-full rounded-md" />
308	                    ))}
309	                  </div>
310	                ) : (
311	                  <Table>
312	                    <TableHeader>
313	                      <TableRow>
314	                        <TableHead className="text-xs">Email</TableHead>
315	                        <TableHead className="text-xs">Role</TableHead>
316	                        <TableHead className="text-xs">Expires</TableHead>
317	                        {canManage && <TableHead className="text-xs w-16" />}
318	                      </TableRow>
319	                    </TableHeader>
320	                    <TableBody>
321	                      {pendingInvitations.map((inv: TeamInvitation) => (
322	                        <TableRow key={inv.id}>
323	                          <TableCell className="text-sm font-medium">{inv.email}</TableCell>
324	                          <TableCell>
325	                            <RoleBadge role={inv.role} />
326	                          </TableCell>
327	                          <TableCell className="text-xs text-muted-foreground">
328	                            {format(new Date(inv.expires_at), "MMM d, yyyy")}
329	                          </TableCell>
330	                          {canManage && (
331	                            <TableCell>
332	                              <Button
333	                                variant="ghost"
334	                                size="icon"
335	                                className="h-7 w-7 text-muted-foreground hover:text-destructive"
336	                                onClick={() => handleRevokeInvite(inv.id, inv.email)}
337	                                disabled={revokingId === inv.id}
338	                                aria-label={`Revoke invite for ${inv.email}`}
339	                              >
340	                                {revokingId === inv.id ? (
341	                                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
342	                                ) : (
343	                                  <Trash2 className="h-3.5 w-3.5" />
344	                                )}
345	                              </Button>
346	                            </TableCell>
347	                          )}
348	                        </TableRow>
349	                      ))}
350	                    </TableBody>
351	                  </Table>
352	                )}
353	              </CardContent>
354	            </Card>
355	          )}
356	
357	          {/* Members table */}
358	          <Card className="border border-border/60 shadow-sm">
359	            <CardHeader className="pb-3">
360	              <div className="flex items-center justify-between">
361	                <CardTitle className="text-sm font-semibold flex items-center gap-2">
362	                  <Users className="h-4 w-4 text-primary" />
363	                  Members
364	                  {!isLoading && (
365	                    <Badge variant="secondary" className="ml-1 text-xs">
366	                      {members.length}
367	                    </Badge>
368	                  )}
369	                </CardTitle>
370	                <Button
371	                  variant="ghost"
372	                  size="icon"
373	                  className="h-7 w-7"
374	                  onClick={() => refetch()}
375	                  disabled={isLoading}
376	                  aria-label="Refresh members"
377	                >
378	                  <RotateCw className={`h-3.5 w-3.5 ${isLoading ? "animate-spin" : ""}`} />
379	                </Button>
380	              </div>
381	            </CardHeader>
382	            <CardContent className="p-0">
383	              {isLoading ? (
384	                <MembersSkeleton />
385	              ) : members.length === 0 ? (
386	                <div className="flex flex-col items-center justify-center py-12 space-y-3 text-center px-4">
387	                  <div className="rounded-xl bg-muted/50 p-4">
388	                    <Users className="h-7 w-7 text-muted-foreground/50" />
389	                  </div>
390	                  <div className="space-y-1">
391	                    <p className="text-sm font-medium text-foreground">No team yet</p>
392	                    <p className="text-sm text-muted-foreground max-w-xs">
393	                      Invite a colleague above to start collaborating on job rankings.
394	                    </p>
395	                  </div>
396	                </div>
397	              ) : (
398	                <Table>
399	                  <TableHeader>
400	                    <TableRow>
401	                      <TableHead className="text-xs">Member</TableHead>
402	                      <TableHead className="text-xs">Role</TableHead>
403	                      <TableHead className="text-xs">Joined</TableHead>
