37	// ─── Component ──────────────────────────────────────────────────────────────
38	
39	const NotificationBell = () => {
40	  const { user } = useAuth();
41	  const [open, setOpen] = useState(false);
42	  const [notifications, setNotifications] = useState<Notification[]>([]);
43	  const [loading, setLoading] = useState(false);
44	
45	  const unreadCount = notifications.filter((n) => !n.read).length;
46	
47	  const fetchNotifications = useCallback(async () => {
48	    if (!user) return;
49	    setLoading(true);
50	    try {
51	      const { data } = await supabase
52	        .from("notifications")
53	        .select("id, type, title, message, read, created_at, metadata")
54	        .eq("user_id", user.id)
55	        .order("created_at", { ascending: false })
56	        .limit(20);
57	      if (data) setNotifications(data as Notification[]);
58	    } catch {
59	      // Silently fail — notifications are non-critical
60	    } finally {
61	      setLoading(false);
62	    }
63	  }, [user]);
64	
65	  // Initial fetch for badge count
66	  useEffect(() => {
67	    fetchNotifications();
68	  }, [fetchNotifications]);
69	
70	  // Refresh when popover opens
71	  useEffect(() => {
72	    if (open) fetchNotifications();
73	  }, [open, fetchNotifications]);
