import { useEffect, useRef, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface ActivityItem {
  id: string;
  team_id: string;
  actor_id: string | null;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  metadata: Record<string, any>;
  created_at: string;
}

const PAGE_SIZE = 50;

/** Map action strings to the filter tab categories */
const ACTION_FILTER_MAP: Record<string, string[]> = {
  Tasks: ["task_created", "task_completed"],
  Notes: ["note_added"],
  Stages: ["stage_changed"],
  Applications: ["application_received"],
  Members: ["member_joined"],
};

function getActionsForFilter(filter: string): string[] | null {
  if (filter === "All") return null;
  return ACTION_FILTER_MAP[filter] ?? null;
}

export function useActivityFeed(
  teamId: string | null,
  filter: string = "All"
) {
  const queryClient = useQueryClient();
  const actions = getActionsForFilter(filter);
  const queryKey = ["activity-feed", teamId, filter];

  // Cursor for pagination (oldest created_at in current set)
  const [before, setBefore] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);

  // Accumulate pages locally so "Load more" appends
  const [allActivities, setAllActivities] = useState<ActivityItem[]>([]);
  const initialLoaded = useRef(false);

  const { data, isLoading, isFetching } = useQuery<ActivityItem[]>({
    queryKey: [...queryKey, before],
    queryFn: async () => {
      if (!teamId) return [];

      let q = (supabase as any)
        .from("activity_log")
        .select("*")
        .eq("team_id", teamId)
        .order("created_at", { ascending: false })
        .limit(PAGE_SIZE + 1); // +1 to detect hasMore

      if (actions && actions.length > 0) {
        q = q.in("action", actions);
      }
      if (before) {
        q = q.lt("created_at", before);
      }

      const { data: rows, error } = await q;
      if (error) throw error;
      return (rows ?? []) as ActivityItem[];
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

  // Merge pages when data arrives
  useEffect(() => {
    if (!data) return;

    const more = data.length > PAGE_SIZE;
    const page = more ? data.slice(0, PAGE_SIZE) : data;
    setHasMore(more);

    if (!before) {
      // First page — reset
      setAllActivities(page);
      initialLoaded.current = true;
    } else {
      // Subsequent page — append
      setAllActivities((prev) => {
        const existingIds = new Set(prev.map((a) => a.id));
        const fresh = page.filter((a) => !existingIds.has(a.id));
        return [...prev, ...fresh];
      });
    }
  }, [data]);

  // Reset when teamId or filter changes
  useEffect(() => {
    setBefore(null);
    setAllActivities([]);
    initialLoaded.current = false;
  }, [teamId, filter]);

  // Realtime subscription — invalidate first-page query on new inserts
  useEffect(() => {
    if (!teamId) return;

    const channel = supabase
      .channel(`activity-log-${teamId}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "activity_log",
          filter: `team_id=eq.${teamId}`,
        },
        (payload) => {
          const newItem = payload.new as ActivityItem;
          // Prepend to the displayed list immediately (optimistic)
          setAllActivities((prev) => {
            if (prev.some((a) => a.id === newItem.id)) return prev;
            return [newItem, ...prev];
          });
          // Also invalidate so first-page re-fetches on next stale check
          queryClient.invalidateQueries({ queryKey: ["activity-feed", teamId, filter] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [teamId, filter, queryClient]);

  function loadMore() {
    if (!hasMore || isFetching) return;
    const last = allActivities[allActivities.length - 1];
    if (last) setBefore(last.created_at);
  }

  return {
    activities: allActivities,
    isLoading: isLoading && allActivities.length === 0,
    isFetching,
    hasMore,
    loadMore,
  };
}

import { formatDistanceToNow } from "date-fns";
import {
  UserPlus,
  CheckSquare,
  CheckCircle2,
  MessageSquare,
  FileText,
  Activity,
} from "lucide-react";
import { cn } from "@/lib/utils";
import type { ActivityItem as ActivityItemType } from "@/hooks/useActivityFeed";

// ─── Action config ────────────────────────────────────────────────────────────

interface ActionConfig {
  icon: typeof Activity;
  color: string;
  bg: string;
  label: (metadata: Record<string, any>) => React.ReactNode;
}

const ACTION_CONFIG: Record<string, ActionConfig> = {
  member_joined: {
    icon: UserPlus,
    color: "text-primary",
    bg: "bg-primary/10",
    label: () => "A new member joined the team",
  },
  task_created: {
    icon: CheckSquare,
    color: "text-orange-600",
    bg: "bg-orange-100 dark:bg-orange-900/20",
    label: (m) => (
      <>
        created task{" "}
        {m.title ? (
          <strong className="font-semibold text-foreground">{m.title}</strong>
        ) : null}
      </>
    ),
  },
  task_completed: {
    icon: CheckCircle2,
    color: "text-emerald-600",
    bg: "bg-emerald-100 dark:bg-emerald-900/20",
    label: (m) => (
      <>
        completed task{" "}
        {m.title ? (
          <strong className="font-semibold text-foreground">{m.title}</strong>
        ) : null}
      </>
    ),
  },
  note_added: {
    icon: MessageSquare,
    color: "text-blue-600",
    bg: "bg-blue-100 dark:bg-blue-900/20",
    label: () => "added a note on a candidate",
  },
  application_received: {
    icon: FileText,
    color: "text-violet-600",
    bg: "bg-violet-100 dark:bg-violet-900/20",
    label: (m) => (
      <>
        {m.name ? (
          <strong className="font-semibold text-foreground">{m.name}</strong>
        ) : (
          "Someone"
        )}{" "}
        applied for a position
      </>
    ),
  },
};

const FALLBACK_CONFIG: ActionConfig = {
  icon: Activity,
  color: "text-muted-foreground",
  bg: "bg-muted",
  label: (_, action) => action.replace(/_/g, " "),
};

// ─── Actor initials helper ────────────────────────────────────────────────────

function actorInitials(actorId: string | null): string {
  if (!actorId) return "SY"; // system
  return actorId.slice(0, 2).toUpperCase();
}

// ─── Props ────────────────────────────────────────────────────────────────────

export interface ActivityItemProps {
  activity: ActivityItemType;
  compact?: boolean;
}

// ─── Component ───────────────────────────────────────────────────────────────

const ActivityItem = ({ activity, compact = false }: ActivityItemProps) => {
  const config = ACTION_CONFIG[activity.action] ?? FALLBACK_CONFIG;
  const Icon = config.icon;

  const timeAgo = formatDistanceToNow(new Date(activity.created_at), {
    addSuffix: true,
  });

  const labelNode =
    typeof config.label === "function"
      ? config.label(activity.metadata)
      : activity.action;

  return (
    <div
      className={cn(
        "flex items-start gap-3",
        compact ? "py-2" : "py-3"
      )}
    >
      {/* Actor avatar */}
      <div
        className={cn(
          "rounded-full flex items-center justify-center shrink-0 font-semibold select-none",
          "bg-primary/10 text-primary",
          compact ? "h-7 w-7 text-[10px]" : "h-8 w-8 text-xs"
        )}
        title={activity.actor_id ?? "system"}
      >
        {actorInitials(activity.actor_id)}
      </div>

      {/* Action icon + text */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1.5 flex-wrap">
          <div
            className={cn(
              "rounded flex items-center justify-center shrink-0",
              config.bg,
              compact ? "h-5 w-5" : "h-6 w-6"
            )}
          >
            <Icon className={cn(compact ? "h-3 w-3" : "h-3.5 w-3.5", config.color)} />
          </div>
          <span
            className={cn(
              "text-muted-foreground leading-snug",
              compact ? "text-xs" : "text-sm"
            )}
          >
            {labelNode}
          </span>
        </div>
        {!compact && (
          <p className="text-[11px] text-muted-foreground/60 mt-0.5">{timeAgo}</p>
        )}
      </div>

      {/* Timestamp — compact shows inline, full shows below */}
      {compact && (
        <span className="text-[10px] text-muted-foreground/50 shrink-0 mt-0.5">
          {timeAgo}
        </span>
      )}
    </div>
  );
};

export default ActivityItem;

import { useState } from "react";
import { Activity as ActivityIcon, Loader2 } from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
import { FadeIn } from "@/components/ui/fade-in";
import { StaggerList } from "@/components/ui/stagger-list";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import ActivityItem from "@/components/ActivityItem";
import { useActivityFeed } from "@/hooks/useActivityFeed";
import { useTeam } from "@/hooks/useTeam";

// ─── Filter tabs ──────────────────────────────────────────────────────────────

const FILTERS = ["All", "Tasks", "Notes", "Stages", "Applications", "Members"] as const;
type Filter = (typeof FILTERS)[number];

// ─── Skeletons ────────────────────────────────────────────────────────────────

function ActivitySkeleton() {
  return (
    <div className="space-y-3 p-4">
      {[1, 2, 3, 4].map((i) => (
        <div key={i} className="flex items-center gap-3">
          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
          <Skeleton className="h-12 flex-1 rounded-lg" />
        </div>
      ))}
    </div>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

const Activity = () => {
  const { team, isLoading: teamLoading } = useTeam();
  const teamId = team?.id ?? null;

  const [activeFilter, setActiveFilter] = useState<Filter>("All");

  const { activities, isLoading, isFetching, hasMore, loadMore } =
    useActivityFeed(teamId, activeFilter);

  const showLoading = isLoading || (teamLoading && !teamId);

  return (
    <SidebarLayout>
      <main className="w-full max-w-2xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <FadeIn>
          <h1 className="text-2xl font-bold text-foreground mb-1">Activity</h1>
          <p className="text-sm text-muted-foreground mb-5">
            See what your team has been up to.
          </p>

          {/* Filter tabs */}
          <div className="flex flex-wrap gap-1.5 mb-5">
            {FILTERS.map((f) => (
              <button
                key={f}
                onClick={() => setActiveFilter(f)}
                className={
                  activeFilter === f
                    ? "px-3 h-7 rounded-full text-xs font-semibold bg-primary text-primary-foreground transition-colors"
                    : "px-3 h-7 rounded-full text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
                }
              >
                {f}
              </button>
            ))}
          </div>
        </FadeIn>

        {/* No team state */}
        {!teamLoading && !teamId && (
          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <ActivityIcon className="h-7 w-7 text-muted-foreground/50" />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">No team yet</p>
              <p className="text-sm text-muted-foreground max-w-xs">
                Create or join a team to see activity here.
              </p>
            </div>
          </div>
        )}

        {/* Loading skeleton */}
        {showLoading && (
          <Card className="border border-border/60 shadow-sm">
            <ActivitySkeleton />
          </Card>
        )}

        {/* Empty state */}
        {!showLoading && teamId && activities.length === 0 && (
          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <ActivityIcon className="h-7 w-7 text-muted-foreground/50" />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium">No activity yet</p>
              <p className="text-sm text-muted-foreground max-w-xs">
                Activity from your team will appear here as things happen.
              </p>
            </div>
          </div>
        )}

        {/* Activity list */}
        {!showLoading && teamId && activities.length > 0 && (
          <StaggerList className="space-y-0" stagger={0.04}>
            <Card className="border border-border/60 shadow-sm">
              <CardContent className="p-0">
                <div className="divide-y divide-border/50">
                  {activities.map((activity) => (
                    <div key={activity.id} className="px-4">
                      <ActivityItem activity={activity} compact={false} />
                    </div>
                  ))}
                </div>

                {/* Load more */}
                {hasMore && (
                  <div className="flex justify-center px-4 py-3 border-t border-border/50">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={loadMore}
                      disabled={isFetching}
                      className="text-xs text-muted-foreground"
                    >
                      {isFetching ? (
                        <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
                      ) : null}
                      Load more
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          </StaggerList>
        )}
      </main>
    </SidebarLayout>
  );
};

export default Activity;

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import type { ActivityItem } from "@/hooks/useActivityFeed";

export interface TasksByAssignee {
  user_id: string;
  pending: number;
  completed: number;
}

export interface TeamDashboardData {
  totalJobs: number;
  activeCandidates: number;
  pendingTasks: number;
  memberCount: number;
  recentActivity: ActivityItem[];
  tasksByAssignee: TasksByAssignee[];
}

export function useTeamDashboard(teamId: string | null) {
  return useQuery<TeamDashboardData>({
    queryKey: ["team-dashboard", teamId],
    queryFn: async () => {
      if (!teamId) {
        return {
          totalJobs: 0,
          activeCandidates: 0,
          pendingTasks: 0,
          memberCount: 0,
          recentActivity: [],
          tasksByAssignee: [],
        };
      }

      const [
        jobsRes,
        pendingTasksRes,
        membersRes,
        activityRes,
        allTasksRes,
      ] = await Promise.all([
        // Total jobs for this team
        (supabase as any)
          .from("jobs")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId),

        // Pending tasks count
        (supabase as any)
          .from("tasks")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId)
          .neq("status", "done"),

        // Team members count
        (supabase as any)
          .from("team_members")
          .select("id", { count: "exact", head: true })
          .eq("team_id", teamId),

        // Last 5 activity items
        (supabase as any)
          .from("activity_log")
          .select("*")
          .eq("team_id", teamId)
          .order("created_at", { ascending: false })
          .limit(5),

        // All tasks for assignee summary (limited columns)
        (supabase as any)
          .from("tasks")
          .select("assigned_to, status")
          .eq("team_id", teamId)
          .not("assigned_to", "is", null),
      ]);

      // Active candidates: count resumes linked to this team's jobs
      // We fetch job IDs first, then count resumes
      let activeCandidates = 0;
      const { data: jobIds } = await (supabase as any)
        .from("jobs")
        .select("id")
        .eq("team_id", teamId);

      if (jobIds && jobIds.length > 0) {
        const ids = (jobIds as { id: string }[]).map((j) => j.id);
        const { count } = await (supabase as any)
          .from("resumes")
          .select("id", { count: "exact", head: true })
          .in("job_id", ids);
        activeCandidates = count ?? 0;
      }

      // Build tasks-by-assignee summary
      const tasksByAssignee: TasksByAssignee[] = [];
      const allTasks = (allTasksRes.data ?? []) as { assigned_to: string; status: string }[];
      const assigneeMap = new Map<string, TasksByAssignee>();

      for (const t of allTasks) {
        if (!t.assigned_to) continue;
        if (!assigneeMap.has(t.assigned_to)) {
          assigneeMap.set(t.assigned_to, { user_id: t.assigned_to, pending: 0, completed: 0 });
        }
        const entry = assigneeMap.get(t.assigned_to)!;
        if (t.status === "done") {
          entry.completed += 1;
        } else {
          entry.pending += 1;
        }
      }
      assigneeMap.forEach((v) => tasksByAssignee.push(v));

      return {
        totalJobs: jobsRes.count ?? 0,
        activeCandidates,
        pendingTasks: pendingTasksRes.count ?? 0,
        memberCount: membersRes.count ?? 0,
        recentActivity: (activityRes.data ?? []) as ActivityItem[],
        tasksByAssignee,
      };
    },
    enabled: !!teamId,
    staleTime: 60_000,
  });
}

